method move_one_ball(arr: seq<int>) returns (result: bool)
    // Precondition: The input array 'arr' can be of any length including zero.
    requires |arr| >= 0
    // Postcondition: The result is true if a non-decreasing order can be achieved by right shifts,
    // otherwise false. If 'arr' is empty, the result is true.
    ensures result == (|arr| == 0 || IsSortedAfterShifts(arr))

    // Helper function to check if the array can be sorted after right shifts
    method IsSortedAfterShifts(arr: seq<int>) returns (canBeSorted: bool)
        // Precondition: The input array 'arr' must have unique elements.
        requires |arr| > 0
        ensures canBeSorted == (exists k: int :: 0 <= k < |arr| && IsSorted(Shift(arr, k)))

    // A method to determine if a sequence is sorted in non-decreasing order
    method IsSorted(seq: seq<int>) returns (sorted: bool)
        requires |seq| > 0
        ensures sorted == (forall i: int :: 0 <= i < |seq| - 1 ==> seq[i] <= seq[i + 1])

    // A method to perform a right shift on the sequence
    method Shift(seq: seq<int>, k: int) returns (shifted: seq<int>)
        requires |seq| > 0 && 0 <= k < |seq|
        ensures |shifted| == |seq| && (forall i: int :: 0 <= i < |seq| ==> shifted[i] == seq[(i - k + |seq|) % |seq|])
